css:
@media print { @page { size: 80mm auto; margin: 3mm; } }
.print-format { width: 80mm; max-width: 80mm; padding: 3mm !important; margin: 0 auto; }
.tk { font-family: "Courier New", monospace; font-size: 11px; line-height: 1.35; color: #000; }
.tk-c { text-align: center; }
.tk-b { font-weight: 700; }
.tk-lg { font-size: 14px; }
.tk-sm { font-size: 9px; word-break: break-all; }
.tk-row { display: flex; justify-content: space-between; gap: 8px; }
.tk-row span:last-child { text-align: right; }
.tk-item { margin-top: 3px; }
.tk-sep { border-top: 1px dashed #000; margin: 5px 0; }
.tk-nocert { border: 1px dashed #000; text-align: center; font-weight: 700; padding: 3px; margin: 5px 0; }
.tk-qr { width: 32mm; height: 32mm; margin-top: 4px; }

html:
{%- set fel = doc.bfel_uuid and doc.bfel_status == "02 Procesada" -%}
{%- set bfel = frappe.db.get_value("BFEL Settings", {"company": doc.company, "enabled": 1}, ["company_nit", "nombrecomercial", "direccionemisor"], as_dict=True) or {} -%}
{%- set pagos = frappe.db.sql("""select pe.mode_of_payment, sum(per.allocated_amount) monto from `tabPayment Entry Reference` per join `tabPayment Entry` pe on pe.name = per.parent where per.reference_doctype = 'Sales Invoice' and per.reference_name = %s and pe.docstatus = 1 group by pe.mode_of_payment""", doc.name, as_dict=True) -%}
<div class="tk">
	<div class="tk-c tk-b tk-lg">{{ bfel.nombrecomercial or doc.company }}</div>
	{% if bfel.company_nit %}<div class="tk-c">NIT {{ bfel.company_nit }}</div>{% endif %}
	{% if bfel.direccionemisor %}<div class="tk-c">{{ bfel.direccionemisor }}</div>{% endif %}
	<div class="tk-sep"></div>
	<div class="tk-row"><span>Factura</span><span class="tk-b">{{ doc.name }}</span></div>
	<div class="tk-row"><span>Fecha</span><span>{{ frappe.utils.formatdate(doc.posting_date) }} {{ (doc.posting_time|string)[:5] }}</span></div>
	<div class="tk-row"><span>Cliente</span><span>{{ doc.customer_name }}</span></div>
	<div class="tk-row"><span>NIT</span><span>{{ doc.tax_id or doc.bfel_nit or "CF" }}</span></div>
	{% if not fel %}<div class="tk-nocert">DOCUMENTO NO CERTIFICADO<br>SIN VALIDEZ FISCAL</div>{% else %}<div class="tk-sep"></div>{% endif %}
	{% for it in doc.items %}
	<div class="tk-item">{{ it.item_name }}</div>
	<div class="tk-row"><span>{{ it.get_formatted("qty") }} x {{ frappe.utils.fmt_money(it.rate) }}</span><span>{{ frappe.utils.fmt_money(it.amount) }}</span></div>
	{% endfor %}
	<div class="tk-sep"></div>
	<div class="tk-row tk-b tk-lg"><span>TOTAL</span><span>{{ frappe.utils.fmt_money(doc.grand_total, currency=doc.currency) }}</span></div>
	<div class="tk-row"><span>IVA incluido</span><span>{{ frappe.utils.fmt_money(doc.total_taxes_and_charges) }}</span></div>
	{% for p in pagos %}
	<div class="tk-row"><span>{{ p.mode_of_payment }}</span><span>{{ frappe.utils.fmt_money(p.monto) }}</span></div>
	{% endfor %}
	{% if doc.outstanding_amount > 0 %}<div class="tk-row tk-b"><span>Saldo pendiente</span><span>{{ frappe.utils.fmt_money(doc.outstanding_amount) }}</span></div>{% endif %}
	{% if fel %}
	<div class="tk-sep"></div>
	<div class="tk-sm">Autorización: {{ doc.bfel_uuid }}</div>
	<div class="tk-sm">Serie: {{ doc.bfel_docto_serie or "" }} &nbsp; No.: {{ doc.bfel_docto_no or "" }}</div>
	{%- set url = "https://felpub.c.sat.gob.gt/verificador-web/publico/vistas/verificacionDte.jsf?tipo=autorizacion&numero=" ~ doc.bfel_uuid ~ "&emisor=" ~ (bfel.company_nit or "") ~ "&receptor=" ~ (doc.tax_id or "CF") ~ "&monto=" ~ doc.grand_total -%}
	{%- set qr = get_qr_base64(url) -%}
	{% if qr %}<div class="tk-c"><img src="{{ qr }}" class="tk-qr"></div>{% endif %}
	{% endif %}
	<div class="tk-sep"></div>
	<div class="tk-c">¡Gracias por su visita!</div>
</div>
